on conflict (id) do update set
  name = excluded.name, aliases = excluded.aliases, location = excluded.location, street = excluded.street, unit = excluded.unit, city = excluded.city, region = excluded.region, postal_code = excluded.postal_code, time_zone_id = excluded.time_zone_id, court_count = excluded.court_count, pricing = excluded.pricing, phone = excluded.phone, website = excluded.website, entrance_note = excluded.entrance_note, attribution = excluded.attribution, location_approximate = excluded.location_approximate, kind = excluded.kind, play_times = excluded.play_times, checked_on = excluded.checked_on,
  status = case when excluded.status = 'verified' then excluded.status else venues.status end,
  hidden_pending_review = venues.hidden_pending_review and venues.review_flag is distinct from 'removed from the official catalog',
  review_flag = nullif(venues.review_flag, 'removed from the official catalog')
where venues.source = excluded.source and venues.merged_into is null;

